    /// Every Emojione shortname (aliases included) → the emoji it stands for.
    static let shortnames: [String: String] = parse(shortnamesData, keyIsHex: false)

    /// Emoji (without variation selectors) → its canonical shortname.
    static let canonicalNames: [String: String] = parse(canonicalData, keyIsHex: true)

    /// Longest emoji sequence in the canonical table, in code points.
    static let longestSequence: Int = canonicalNames.keys.reduce(0) { max($0, $1.unicodeScalars.count) }

    private static func emoji(fromHex hex: Substring) -> String {
        var s = String.UnicodeScalarView()
        for part in hex.split(separator: "-") { if let v = UInt32(part, radix: 16), let u = Unicode.Scalar(v) { s.append(u) } }
        return String(s)
    }

    private static func parse(_ data: String, keyIsHex: Bool) -> [String: String] {
        var out: [String: String] = [:]
        for word in data.split(whereSeparator: { $0 == " " || $0 == "\n" }) {
            guard let eq = word.firstIndex(of: "=") else { continue }
            let l = word[..<eq], r = word[word.index(after: eq)...]
            if keyIsHex { out[emoji(fromHex: l)] = String(r) } else { out[String(l)] = emoji(fromHex: r) }
        }
        return out
    }

